const body=$('Entrada voz autenticada').first().json.body||{};
const accion=String(body.accion||'consultar_estado');
if(accion==='consultar_catalogo') return [{json:{modo:'SIMULADO',fuente:'catalogo_ficticio_v1',moneda:'MXN',precios:{cuaderno:35,pluma:8,lapiz:6,borrador:5,carpeta:20},nota:'Precios ficticios por pieza; no se realizan compras.'}}];
const folio=String(body.caso_id||'').trim().toUpperCase();
if(accion!=='consultar_estado'||!/^AULA-\d{1,20}$/.test(folio)) return [{json:{ok:false,error:'Indica un folio AULA seguido de numeros. Solo se permiten consultas.'}}];
const row=$input.all().map(i=>i.json).find(r=>r.caso_id===folio);
if(!row) return [{json:{ok:false,caso_id:folio,error:'Caso no encontrado. No inventes un resultado.'}}];
return [{json:{ok:true,modo:'SIMULADO',caso_id:row.caso_id,estado:row.estado,version:row.version,total_mxn:row.total_mxn,fuente:'aula_casos',consultado_en:new Date().toISOString(),nota:'Estado almacenado. Las decisiones se registran solo mediante Telegram autorizado.'}}];
